-- Profiles (extends auth.users)
create table profiles (
  id uuid primary key references auth.users on delete cascade,
  username text unique not null,
  avatar_url text,
  stripe_account_id text, -- for Stripe Connect payouts
  created_at timestamptz default now()
);

-- Listings
create table listings (
  id uuid primary key default gen_random_uuid(),
  seller_id uuid references profiles(id) on delete cascade not null,
  title text not null,
  description text,
  price_cents int not null check (price_cents >= 0),
  currency text default 'usd',
  images text[] default '{}',
  status text default 'active' check (status in ('active','sold','removed')),
  created_at timestamptz default now()
);
create index on listings(seller_id);
create index on listings(status, created_at desc);

-- Conversations + messages
create table conversations (
  id uuid primary key default gen_random_uuid(),
  listing_id uuid references listings(id) on delete cascade,
  buyer_id uuid references profiles(id) not null,
  seller_id uuid references profiles(id) not null,
  created_at timestamptz default now(),
  unique(listing_id, buyer_id)
);

create table messages (
  id uuid primary key default gen_random_uuid(),
  conversation_id uuid references conversations(id) on delete cascade not null,
  sender_id uuid references profiles(id) not null,
  body text not null,
  created_at timestamptz default now()
);
create index on messages(conversation_id, created_at);

-- Orders (created when buyer pays)
create table orders (
  id uuid primary key default gen_random_uuid(),
  listing_id uuid references listings(id) not null,
  buyer_id uuid references profiles(id) not null,
  seller_id uuid references profiles(id) not null,
  amount_cents int not null,
  platform_fee_cents int not null,
  stripe_payment_intent_id text unique,
  status text default 'pending' check (status in ('pending','paid','refunded','failed')),
  created_at timestamptz default now()
);

-- RLS
alter table profiles enable row level security;
alter table listings enable row level security;
alter table conversations enable row level security;
alter table messages enable row level security;
alter table orders enable row level security;

create policy "profiles readable" on profiles for select using (true);
create policy "profiles self-update" on profiles for update using (auth.uid() = id);

create policy "listings readable" on listings for select using (status = 'active' or seller_id = auth.uid());
create policy "listings self-insert" on listings for insert with check (auth.uid() = seller_id);
create policy "listings self-update" on listings for update using (auth.uid() = seller_id);

create policy "conversations participants" on conversations for select
  using (auth.uid() = buyer_id or auth.uid() = seller_id);
create policy "conversations create" on conversations for insert
  with check (auth.uid() = buyer_id);

create policy "messages participants read" on messages for select using (
  exists (select 1 from conversations c
    where c.id = messages.conversation_id
      and (c.buyer_id = auth.uid() or c.seller_id = auth.uid()))
);
create policy "messages send" on messages for insert with check (
  auth.uid() = sender_id and exists (
    select 1 from conversations c
    where c.id = conversation_id
      and (c.buyer_id = auth.uid() or c.seller_id = auth.uid()))
);

create policy "orders participants" on orders for select
  using (auth.uid() = buyer_id or auth.uid() = seller_id);
```

**`hooks/useMessages.ts`** — realtime messaging in ~30 lines
```ts
import { useEffect } from 'react';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { supabase } from '../lib/supabase';

export function useMessages(conversationId: string) {
  const qc = useQueryClient();

  const query = useQuery({
    queryKey: ['messages', conversationId],
    queryFn: async () => {
      const { data, error } = await supabase
        .from('messages')
        .select('*')
        .eq('conversation_id', conversationId)
        .order('created_at', { ascending: true });
      if (error) throw error;
      return data;
    },
  });

  useEffect(() => {
    const channel = supabase
      .channel(`messages:${conversationId}`)
      .on('postgres_changes',
        { event: 'INSERT', schema: 'public', table: 'messages',
          filter: `conversation_id=eq.${conversationId}` },
        (payload) => {
          qc.setQueryData(['messages', conversationId], (old: any[] = []) =>
            [...old, payload.new]);
        }
      )
      .subscribe();
    return () => { supabase.removeChannel(channel); };
  }, [conversationId]);

  return query;
}

export async function sendMessage(conversationId: string, body: string) {
  const { data: { user } } = await supabase.auth.getUser();
  return supabase.from('messages').insert({
    conversation_id: conversationId,
    sender_id: user!.id,
    body,
  });
}
```

